/*@ requires vl<=32; assigns \nothing; ensures \forall integer j;0<=j<vl ==> \result.lane[j]==(m.lane[j]?x:\at(a,Pre).lane[j]); */
vuint32m8_t __riscv_vmerge_vxm_u32m8(vuint32m8_t a,uint32_t x,vbool4_t m,size_t vl) { /*@ loop invariant 0<=i<=vl; loop invariant \forall integer j;0<=j<i ==> a.lane[j]==(m.lane[j]?x:\at(a,Pre).lane[j]); loop invariant \forall integer j;i<=j<vl ==> a.lane[j]==\at(a,Pre).lane[j]; loop assigns i,a; loop variant vl-i; */ for(size_t i=0;i<vl;i++)if(m.lane[i])a.lane[i]=x;return a; }
